SELECT
FROM sys_link sl WHERE sl.active = 1
AND (sl.title LIKE CONCAT('%', #{condition.q}, '%') OR sl.sub_title LIKE CONCAT('%', #{condition.q}, '%') OR sl.description LIKE CONCAT('%', #{condition.q}, '%') OR sl.summary LIKE CONCAT('%', #{condition.q}, '%'))
AND EXISTS(SELECT 1 FROM sys_dict_relation sdr INNER JOIN sys_dict sd ON (sdr.dict_id = sd. id) WHERE sdr.biz_id = sl. id AND sd. code IN
#{code}
)
